import assert from 'node:assert/strict';import fs from 'node:fs';import os from 'node:os';import path from 'node:path';import {createRequire} from 'node:module';
const require=createRequire(import.meta.url),{createStorage}=require('../../shell/storage/index.cjs');
assert.ok(process.env.PT_PG_DSN,'Disposable PostgreSQL required');const temp=fs.mkdtempSync(path.join(os.tmpdir(),'northstar-upgrade-pg-')),old=path.join(temp,'old');fs.mkdirSync(old);for(const name of fs.readdirSync('shell/db-migrations'))if(/^\d+.*\.sql$/.test(name)&&Number(name.slice(0,3))<=23)fs.copyFileSync(path.join('shell/db-migrations',name),path.join(old,name));
let store;try{
 const opts={dataDir:path.join(temp,'unused'),masterKeyFile:path.join(temp,'key')};store=await createStorage({...opts,migrationsDir:old});
 const user=(await store.repositories.auth.register({username:'upgrade-local-fixture',password:'FixturePass123'})).user;
 const conv=await store.repositories.conversations.create(user.id),messages=[{role:'user',text:'UPGRADE_PRESERVE_FIXTURE',ts:'2026-11-02T00:00:00Z'}];await store.repositories.conversations.saveMessages(user.id,conv.id,messages);await store.repositories.memory.set(user.id,'fixture','prior memory');await store.repositories.keys.encryptApiKey(user.id,'fixture-not-live-key');await store.close();store=null;
 store=await createStorage(opts);assert.deepEqual((await store.repositories.conversations.get(user.id,conv.id)).messages,messages);assert.equal((await store.repositories.memory.list(user.id))[0].value,'prior memory');assert.equal(await store.repositories.keys.decryptApiKey(user.id),'fixture-not-live-key');
 const migrated=(await store.adapter.query('SELECT provenance,confirmed FROM memory_records WHERE user_id=$1 AND key=$2',[user.id,'fixture'])).rows[0];assert.equal(migrated.provenance,'user-verbatim-statement');assert.equal(migrated.confirmed,false);
 const schema=(await store.adapter.query('SELECT native_session_id,skill_context_hash FROM conversations WHERE id=$1',[conv.id])).rows[0];assert.equal(schema.native_session_id,null);assert.equal(schema.skill_context_hash,'');
 const before=(await store.adapter.query('SELECT name FROM schema_migrations ORDER BY name')).rows;await store.migrate();assert.deepEqual((await store.adapter.query('SELECT name FROM schema_migrations ORDER BY name')).rows,before);assert.ok(before.some(row=>row.name==='028_skill_publication.sql'));
 if(process.env.NORTHSTAR_ROLLBACK_ROOT){await store.close();store=null;const oldStorage=require(path.resolve(process.env.NORTHSTAR_ROLLBACK_ROOT,'shell/storage/index.cjs'));store=await oldStorage.createStorage(opts);assert.deepEqual((await store.repositories.conversations.get(user.id,conv.id)).messages,messages);assert.equal((await store.repositories.memory.list(user.id))[0].value,'prior memory');assert.equal(await store.repositories.keys.decryptApiKey(user.id),'fixture-not-live-key');}
 console.log(JSON.stringify({rollbackRepositoryRead:!!process.env.NORTHSTAR_ROLLBACK_ROOT,status:'R24_POSTGRES_UPGRADE_PASS',prior:'001-023',current:'001-028',preserved:['conversation','memory','encrypted-key'],legacyMemory:'unconfirmed',replay:'idempotent'}));
}finally{await store?.close();fs.rmSync(temp,{recursive:true,force:true});}
